package com.estoqueinteligente.auth;import jakarta.validation.constraints.*;public class RegisterRequest{@NotBlank(message="O nome é obrigatório")@Size(max=150)private String name;@NotBlank(message="O e-mail é obrigatório")@Email(message="Informe um e-mail válido")@Size(max=180)private String email;@NotBlank(message="A senha é obrigatória")@Size(min=6,message="A senha deve ter ao menos 6 caracteres")private String password;@NotNull(message="O perfil é obrigatório")private UserRole role;public RegisterRequest(){}public String getName(){return name;}public void setName(String v){name=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public UserRole getRole(){return role;}public void setRole(UserRole v){role=v;}}
